def transform(grid):
    h, w = len(grid), len(grid[0])
    pos = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c]: pos[grid[r][c]].append((r,c))
    boxes = []
    for color, cells in pos.items():
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
        # A rectangular frame has a complete monochrome perimeter; all of
        # its same-colored contents lie inside this bounding rectangle.
        if r1-r0 < 2 or c1-c0 < 2: continue
        if all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1)):
            boxes.append((color,r0,r1,c0,c1))
    sources = []
    for color,r0,r1,c0,c1 in boxes:
        pat = [[grid[r][c] == color for c in range(c0+1,c1)] for r in range(r0+1,r1)]
        if any(any(row) for row in pat):
            sources.append((color,r0,r1,c0,c1,pat))
    if len(sources) != 1: return [row[:] for row in grid]
    src_color,sr0,sr1,sc0,sc1,pat = sources[0]
    out = [row[:] for row in grid]
    ph,pw=len(pat),len(pat[0])
    for color,r0,r1,c0,c1 in boxes:
        if (color,r0,r1,c0,c1)==(src_color,sr0,sr1,sc0,sc1): continue
        # Remove the empty frame, restoring it only when its cavity matches.
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if out[r][c] == color: out[r][c] = 0
        if r1-r0-1 == ph and c1-c0-1 == pw:
            for i in range(ph):
                for j in range(pw):
                    if pat[i][j]: out[r0+1+i][c0+1+j] = color
    return out
